         TextWriter writer,
         string format,
         string subcommand,
         string cause,
         string detail,
         string fix,
         CrossRuntimeReviewResolution? resolution = null)
     {
         var refusal = new CrossRuntimeReviewRefusal
         {
             Command = $"{CommandName} {subcommand}",
             Outcome = "refused",
             Cause = cause,
             Detail = detail,
             Fix = fix,
             Resolution = resolution,
         };

