                 .ThenBy(entry => entry.File, StringComparer.Ordinal)
                 .ToArray(),
             Unreadable = unreadable,
         };
     }

     private sealed record EpochBoundary(DateTimeOffset RecordedAt, string FileName);

     private static EpochBoundary? ComputeEpochBoundary(
